                        implies_apply(ex_j.suffix(idx), p.and(next), later(p).or(later(q)));
                        // (later(p).or(later(q))).satisfied_by(ex_j.suffix(idx))
                        assert (later(p).or(later(q))).satisfied_by(ex_j.suffix(idx));
                        // = later(p).satisfied_by(ex_j.suffix(idx)) || later(q).satisfied_by(ex_j.suffix(idx))
                        // = p.satisfied_by(ex_j.suffix(idx).suffix(1)) || q.satisfied_by(ex_j.suffix(idx).suffix(1))
                        // Connect ex_j.suffix(idx).suffix(1) == ex_j.suffix(idx + 1)
                        suffix_add_one(ex_j, idx);
                        assert ex_j.suffix(idx).suffix(1) == ex_j.suffix(idx + 1);
                        // Now conclude
                        assert later(p).satisfied_by(ex_j.suffix(idx)) || later(q).satisfied_by(ex_j.suffix(idx));
                        assert p.satisfied_by(ex_j.suffix(idx).suffix(1)) || q.satisfied_by(ex_j.suffix(idx).suffix(1));
                        assert p.satisfied_by(ex_j.suffix(idx + 1)) || q.satisfied_by(ex_j.suffix(idx + 1));
                    }
                };

                // Now use always_p_or_eventually_q_rec to show always(p) on ex_j
                assert forall |k: nat| p.satisfied_by(#[trigger] ex_j.suffix(k)) by {
                    always_p_or_eventually_q_rec(ex_j, next, p, q, k);
                };

                // Therefore always(p).satisfied_by(ex_j)
                assert always(p).satisfied_by(ex_j);
                assert (always(p).or(eventually(q))).satisfied_by(ex_j);
            } else {
                // eventually(q) holds on ex_j
                assert (always(p).or(eventually(q))).satisfied_by(ex_j);
            }
        }
    };
}

