        always(p.and(next).implies(later(p).or(later(q)))).satisfied_by(ex),
        always(next).satisfied_by(ex),
    ensures always(p.implies(always(p).or(eventually(q)))).satisfied_by(ex),
{
    assert forall |j: nat| (p.implies(always(p).or(eventually(q)))).satisfied_by(#[trigger] ex.suffix(j)) by {
        let ex_j = ex.suffix(j);

        // Propagate always properties to ex_j
        always_propagate_forwards(ex, p.and(next).implies(later(p).or(later(q))), j);
        always_propagate_forwards(ex, next, j);

        // Unfold always on ex_j
        always_unfold(ex_j, p.and(next).implies(later(p).or(later(q))));
        always_unfold(ex_j, next);

        if p.satisfied_by(ex_j) {
            if !eventually(q).satisfied_by(ex_j) {
                // not(eventually(q)) holds on ex_j
                assert(not(eventually(q)).satisfied_by(ex_j));
                not_eventually_unfold(ex_j, q);

                // Establish premise 1 for always_p_or_eventually_q_rec
                assert forall |idx: nat| p.satisfied_by(ex_j.suffix(idx)) && next.satisfied_by(ex_j.suffix(idx)) ==> p.satisfied_by(ex_j.suffix(idx + 1)) || q.satisfied_by(ex_j.suffix(idx + 1)) by {
                    if p.satisfied_by(ex_j.suffix(idx)) && next.satisfied_by(ex_j.suffix(idx)) {
                        assert((p.and(next)).satisfied_by(ex_j.suffix(idx)));
                        implies_apply(ex_j.suffix(idx), p.and(next), later(p).or(later(q)));
                        assert((later(p).or(later(q))).satisfied_by(ex_j.suffix(idx)));
                        suffix_add_one(ex_j, idx);
                        assert(ex_j.suffix(idx).suffix(1) == ex_j.suffix(idx + 1));
                        assert(later(p).satisfied_by(ex_j.suffix(idx)) || later(q).satisfied_by(ex_j.suffix(idx)));
                        assert(p.satisfied_by(ex_j.suffix(idx).suffix(1)) || q.satisfied_by(ex_j.suffix(idx).suffix(1)));
                        assert(p.satisfied_by(ex_j.suffix(idx + 1)) || q.satisfied_by(ex_j.suffix(idx + 1)));
